const errors = [];
const LABS = { thsottiaux: 'OpenAI' };
const HOSTS = ['x.com', 'twitter.com', 'codex-resets.com'];

function safeAll(name) {
  try { return $(name).all().map(i => i.json || {}); } catch (e) { return []; }
}
function validUrl(u) {
  if (typeof u !== 'string') return null;
  const s = u.trim();
  return /^https:\/\/(?:www\.)?(?:x\.com|twitter\.com)\/thsottiaux\/status\/\d+$/.test(s)
    ? s.replace('https://www.', 'https://').replace('https://twitter.com/', 'https://x.com/') : null;
}
function toIso(v) {
  if (v === undefined || v === null || v === '') return null;
  const d = typeof v === 'number' ? new Date(v < 1e12 ? v * 1000 : v) : new Date(v);
  return isNaN(d.getTime()) ? null : d.toISOString();
}
function snowflakeIso(id) {
  try { return new Date(Number((BigInt(String(id)) >> 22n) + 1288834974657n)).toISOString(); } catch (e) { return null; }
}
function asObj(j) {
  if (typeof j === 'string') { try { return JSON.parse(j); } catch (e) { return null; } }
  if (j && typeof j.data === 'string') { try { return JSON.parse(j.data); } catch (e) { return j; } }
  return j;
}
function isErr(j) { return !j || (j.error && !j.data && !j.html && !j.id); }
function decodeHtml(s) {
  return String(s || '').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');
}

// ---------- Resets ----------
let resetsOk = false;
const resets = [];
const resetIds = new Set();
const resetUrlById = {};
for (const raw of safeAll('Fetch Reset History')) {
  const j = asObj(raw);
  if (!j || !Array.isArray(j.data)) {
    if (raw && raw.error) errors.push('resets API: ' + (raw.error.message || JSON.stringify(raw.error)).slice(0, 200));
    continue;
  }
  resetsOk = true;
  for (const r of j.data) {
    if (!r || !r.id) continue;
    const id = String(r.id);
    resetIds.add(id);
    const url = validUrl(r.source && r.source.url) || validUrl('https://x.com/thsottiaux/status/' + id);
    if (url) resetUrlById[id] = url;
    if (resets.some(x => x.id === id)) continue;
    const kind = r.reset_type === 'banked' ? 'banked' : 'regular';
    const announcedAt = toIso(r.announced_at) || snowflakeIso(id);
    if (!url) { errors.push('reset ' + id + ': invalid source url'); continue; }
    resets.push({ id, kind, announcedAt, url });
  }
}
if (!resetsOk) errors.push('resets API failed or returned no data');
resets.sort((a, b) => String(b.announcedAt).localeCompare(String(a.announcedAt)));

// ---------- Status ----------
const statusRaw = asObj(safeAll('Fetch Reset Status')[0]);
let status = { latestResetId: resets[0] ? resets[0].id : null, latestResetAt: resets[0] ? resets[0].announcedAt : null, totalResets: resets.length };
if (statusRaw && statusRaw.data) {
  const d = statusRaw.data;
  status = {
    latestResetId: d.latest_reset && d.latest_reset.id ? String(d.latest_reset.id) : status.latestResetId,
    latestResetAt: toIso(d.latest_reset && d.latest_reset.announced_at) || toIso(d.stats && d.stats.last_reset_at) || status.latestResetAt,
    totalResets: d.stats && typeof d.stats.total === 'number' ? d.stats.total : status.totalResets,
  };
} else {
  errors.push('status API failed; status derived from reset history');
}

// ---------- Tibo-28 page ----------
let pageOk = false;
const entries = [];
const pageItem = safeAll('Fetch Tibo-28 Page')[0] || {};
const html = typeof pageItem.html === 'string' ? pageItem.html : (typeof pageItem.data === 'string' ? pageItem.data : '');
if (!html) {
  errors.push('tibo-28 page fetch failed' + (pageItem.error ? ': ' + String(pageItem.error.message || pageItem.error).slice(0, 200) : ''));
} else {
  // ld+json ItemList
  let list = null;
  const scriptRe = /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  let m;
  while ((m = scriptRe.exec(html)) && !list) {
    try {
      const data = JSON.parse(m[1]);
      const nodes = Array.isArray(data) ? data : (Array.isArray(data['@graph']) ? data['@graph'] : [data]);
      for (const n of nodes) {
        const t = n && n['@type'];
        if (t === 'ItemList' || (Array.isArray(t) && t.includes('ItemList'))) { list = n; break; }
      }
    } catch (e) { errors.push('ld+json parse error'); }
  }
  // article -> day map
  const articleInfo = {};
  const tokenRe = /<li\b[^>]*\bid=["']day-(\d+)["'][^>]*>|<article\b([^>]*)>/gi;
  let currentDay = null;
  let t;
  while ((t = tokenRe.exec(html))) {
    if (t[1]) { currentDay = parseInt(t[1], 10); continue; }
    const attrs = t[2] || '';
    const idm = attrs.match(/\bid=["']announcement-([^"']+)["']/i);
    if (!idm) continue;
    let frag;
    try { frag = decodeURIComponent(idm[1]); } catch (e) { frag = idm[1]; }
    const pid = frag.replace(/^post:/, '');
    const cls = (attrs.match(/\bclass=["']([^"']*)["']/i) || [])[1] || '';
    articleInfo[pid] = { day: currentDay, improvement: /challenge-entry--improvement/.test(cls) };
  }
  if (!list || !Array.isArray(list.itemListElement)) {
    errors.push('tibo-28: ld+json ItemList not found');
  } else {
    pageOk = true;
    for (const el of list.itemListElement) {
      const it = (el && el.item) || el || {};
      const ref = String(it.url || it['@id'] || '');
      let frag = ref.includes('#') ? ref.slice(ref.indexOf('#') + 1) : '';
      try { frag = decodeURIComponent(frag); } catch (e) {}
      const pid = frag.replace(/^announcement-/, '').replace(/^post:/, '');
      if (!pid) { errors.push('tibo-28: item without announcement id'); continue; }
      if (entries.some(e => e.id === pid)) continue;
      const info = articleInfo[pid];
      const title = decodeHtml(it.name).trim();
      const summary = decodeHtml(it.description).trim();
      const url = validUrl(it.citation) || resetUrlById[pid] || null;
      if (!info || !Number.isInteger(info.day) || info.day < 1 || info.day > 28) { errors.push('tibo-28 ' + pid + ': no valid day section'); continue; }
      if (!title) { errors.push('tibo-28 ' + pid + ': missing title'); continue; }
      if (!url) { errors.push('tibo-28 ' + pid + ': invalid source url'); continue; }
      const kind = resetIds.has(pid) || !info.improvement ? 'reset' : 'improvement';
      entries.push({ id: pid, day: info.day, kind, title, summary, url, sortOrder: Number(el.position) || entries.length + 1 });
    }
  }
}
entries.sort((a, b) => a.day - b.day || a.sortOrder - b.sortOrder);

// Raw posts are retained for conversation; they never decide whether an alert is sent.
const updates = [];
const seen = new Set();
const items = safeAll('Fetch Lab Posts (Apify)');
const countsByInput = {};
let apifyFailed = false;
for (const tw of items) {
  if (tw.error || tw.success === false) { apifyFailed = true; continue; }
  if (tw.success !== true) continue;
  const inputKey = tw.inputType + ':' + tw.inputValue;
  countsByInput[inputKey] = (countsByInput[inputKey] || 0) + 1;
  const id = String(tw.tweetId || '');
  const text = String(tw.text || '').trim();
  // Profile results can omit author metadata; only the requested Tibo profile can fill it in.
  const author = String(tw.authorUsername || (tw.author && tw.author.username) ||
    (tw.inputType === 'profile' && /^(?:@)?thsottiaux$/i.test(tw.inputValue || '') ? 'thsottiaux' : '')).replace(/^@/, '').toLowerCase();
  if (author !== 'thsottiaux' || !/^\d+$/.test(id) || !text || seen.has(id)) continue;
  const url = validUrl(tw.url || 'https://x.com/thsottiaux/status/' + id);
  if (!url || !/^https:\/\/(?:www\.)?(?:x\.com|twitter\.com)\/thsottiaux\/status\/\d+/.test(url)) continue;
  const announcedAt = toIso(tw.createdAt);
  if (!announcedAt) continue;
  seen.add(id);
  const attribution = tw.isRetweet ? '[Repost] ' : tw.isReply ? '[Reply] ' : '';
  updates.push({id, author, lab:'OpenAI', kind:'post', title:attribution+text.slice(0,100),
    summary:attribution+text, announcedAt, url});
}
const capped = Object.values(countsByInput).some(n => n >= 10);
if (apifyFailed || !items.length) errors.push('Apify collection failed; previously collected posts retained');
if (capped) errors.push('Apify latest-10 post window filled; daily post coverage may be partial');
updates.sort((a,b) => b.announcedAt.localeCompare(a.announcedAt));
return [{json:{ok:resetsOk || pageOk, fetchedAt:new Date().toISOString(), errors, entries,resets,updates,status,
  counts:{entries:entries.length,resets:resets.length,updates:updates.length,apifyPosts:updates.length}}}];
